const now = Date.now();
const DAY = 24 * 60 * 60 * 1000;
const todayStr = new Date().toISOString().split('T')[0];
const closedStages = new Set(['closedwon', 'closedlost', 'closed_won', 'closed_lost']);
const out = [];

const unwrap = (prop) => {
  if (prop === null || prop === undefined) return '';
  if (typeof prop === 'object' && 'value' in prop) return prop.value ?? '';
  return prop;
};

const parseDateMs = (raw) => {
  const val = unwrap(raw);
  if (val === '' || val === null || val === undefined) return NaN;
  const num = Number(val);
  if (Number.isFinite(num) && num > 0) return num;
  return new Date(val).getTime();
};

for (const item of $input.all()) {
  const d = item.json;
  const p = d.properties ?? d;
  const dealId = unwrap(d.dealId) || unwrap(d.id) || unwrap(p.hs_object_id);
  if (!dealId) continue;

  const rawStage = String(unwrap(p.dealstage) || '');
  const stage = rawStage.toLowerCase();
  if (!stage || closedStages.has(stage) || stage.includes('closedwon') || stage.includes('closedlost')) continue;

  const existingDesc = String(unwrap(p.description) || '');
  if (existingDesc.includes(`=== DEAL RESCUE AUDIT (${todayStr}) ===`)) {
    continue;
  }

  const lastActivityRaw = unwrap(p.hs_last_sales_activity_date) || unwrap(p.notes_last_updated) || unwrap(p.hs_lastmodifieddate);
  const lastActivity = parseDateMs(lastActivityRaw);
  const nextActivity = parseDateMs(p.hs_next_activity_date);
  const closeDateMs = parseDateMs(p.closedate);

  const daysSinceActivity = Number.isFinite(lastActivity) ? Math.max(0, Math.floor((now - lastActivity) / DAY)) : null;
  const daysToClose = Number.isFinite(closeDateMs) ? Math.ceil((closeDateMs - now) / DAY) : null;
  const nextActivityOverdue = Number.isFinite(nextActivity) && nextActivity < now;
  const hasNoNextActivity = !Number.isFinite(nextActivity);

  let score = 0;
  const reasons = [];

  if (daysSinceActivity === null) {
    score += 25;
    reasons.push('No recorded sales activity date');
  } else if (daysSinceActivity >= 14) {
    score += 45;
    reasons.push(`No sales activity for ${daysSinceActivity} days`);
  } else if (daysSinceActivity >= 7) {
    score += 30;
    reasons.push(`No sales activity for ${daysSinceActivity} days`);
  } else if (daysSinceActivity >= 4) {
    score += 15;
    reasons.push(`Last sales activity was ${daysSinceActivity} days ago`);
  }

  if (nextActivityOverdue) {
    score += 30;
    reasons.push('Scheduled next activity is overdue');
  } else if (hasNoNextActivity) {
    score += 15;
    reasons.push('No next step scheduled on calendar');
  }

  if (daysToClose !== null && daysToClose >= 0 && daysToClose <= 3) {
    score += 25;
    reasons.push(`Close date approaching in ${daysToClose} day(s)`);
  } else if (daysToClose !== null && daysToClose < 0) {
    score += 30;
    reasons.push(`Close date slipped (${Math.abs(daysToClose)} day(s) overdue)`);
  }

  if ((stage.includes('contract') || stage.includes('proposal')) && daysSinceActivity !== null && daysSinceActivity >= 5) {
    score += 20;
    reasons.push(`Proposal/Contract sent ${daysSinceActivity} days ago with no response`);
  }

  score = Math.min(score, 100);
  if (score < 30) continue;

  const parsedAmount = Number(unwrap(p.amount));
  const amount = Number.isFinite(parsedAmount) ? parsedAmount : 0;
  const initialRiskLevel = score >= 70 ? 'HIGH' : score >= 45 ? 'MEDIUM' : 'LOW';
  const ruleDiagnosis = nextActivityOverdue
    ? 'FOLLOW_UP_MISSED'
    : (daysSinceActivity !== null && daysSinceActivity >= 7)
      ? 'GHOSTED_PROSPECT'
      : (daysToClose !== null && daysToClose <= 3)
        ? 'CLOSING_DATE_RISK'
        : 'FOLLOW_UP_MISSED';

  out.push({
    json: {
      dealId: String(dealId),
      dealName: String(unwrap(p.dealname) || 'Unnamed Deal'),
      amount,
      dealstage: rawStage,
      pipeline: String(unwrap(p.pipeline) || 'default'),
      ownerId: String(unwrap(p.hubspot_owner_id) || ''),
      closeDate: Number.isFinite(closeDateMs) ? new Date(closeDateMs).toISOString().split('T')[0] : 'Not Set',
      daysSinceActivity: daysSinceActivity !== null ? daysSinceActivity : 'Unknown',
      daysToClose: daysToClose !== null ? daysToClose : 'Unknown',
      nextActivityOverdue,
      hasNoNextActivity,
      ruleRiskScore: score,
      ruleRiskLevel: initialRiskLevel,
      ruleDiagnosis,
      riskSignals: reasons.join(' · '),
      existingDescription: existingDesc
    }
  });
}

out.sort((a, b) => (b.json.ruleRiskScore - a.json.ruleRiskScore) || (b.json.amount - a.json.amount));
return out;

const deal = $('Loop Over Deal Batches').item.json;
const notesRes = $('Post Notes Search HubSpot API').item.json;
const emailsRes =$input.first().json;

const stripHtml = (str) => String(str || '').replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim();

const notesList = (notesRes?.results || []).map((n, idx) => {
  const date = n.properties?.hs_timestamp ? n.properties.hs_timestamp.split('T')[0] : 'Unknown date';
  const body = stripHtml(n.properties?.hs_note_body).slice(0, 350);
  return `[Note ${idx + 1} - ${date}]: ${body}`;
});

const emailsList = (emailsRes?.results || []).map((e, idx) => {
  const date = e.properties?.hs_timestamp ? e.properties.hs_timestamp.split('T')[0] : 'Unknown date';
  const dir = e.properties?.hs_email_direction || 'EMAIL';
  const subj = e.properties?.hs_email_subject || '(No Subject)';
  const snippet = stripHtml(e.properties?.hs_email_text).slice(0, 350);
  return `[${dir} ${idx + 1} - ${date}] Subject: "${subj}" | Snippet: ${snippet}`;
});

const emailStatusText = emailsRes?.error
  ? 'Email timeline unavailable (sales-email-read scope not enabled on HubSpot OAuth); rely on deal properties and CRM notes.'
  : (emailsList.length ? emailsList.join('\n') : 'No recent CRM emails logged.');

const timelineDigest = [
  notesList.length ? notesList.join('\n') : 'No recent CRM notes logged.',
  emailStatusText
].join('\n\n');

return [
  {
    json: {
      dealId: String(deal.dealId || ''),
      dealName: String(deal.dealName || 'Unnamed Deal'),
      amount: Number(deal.amount || 0),
      dealstage: String(deal.dealstage || ''),
      pipeline: String(deal.pipeline || 'default'),
      ownerId: String(deal.ownerId || ''),
      closeDate: String(deal.closeDate || 'Not Set'),
      daysSinceActivity: deal.daysSinceActivity ?? 'Unknown',
      daysToClose: deal.daysToClose ?? 'Unknown',
      nextActivityOverdue: Boolean(deal.nextActivityOverdue),
      hasNoNextActivity: Boolean(deal.hasNoNextActivity),
      ruleRiskScore: Number(deal.ruleRiskScore ?? 0),
      ruleRiskLevel: String(deal.ruleRiskLevel || 'LOW'),
      ruleDiagnosis: String(deal.ruleDiagnosis || 'FOLLOW_UP_MISSED'),
      riskSignals: String(deal.riskSignals || ''),
      existingDescription: String(deal.existingDescription || ''),
      timelineDigest
    }
  }
];

