const deal = $('Build Timeline Context').item.json;
const aiRaw =$input.first().json;

let parsed = {};
try {
  if (aiRaw?.output && typeof aiRaw.output === 'object') {
    parsed = aiRaw.output;
  } else if (typeof aiRaw?.output === 'string') {
    parsed = JSON.parse(aiRaw.output.replace(/```json|```/g, '').trim());
  } else if (aiRaw?.classification) {
    parsed = aiRaw;
  }
} catch (e) {
  parsed = {};
}

const classification = parsed.classification || deal.ruleDiagnosis;
const riskLevel = parsed.riskLevel || deal.ruleRiskLevel;
const aiDiagnosis = parsed.aiDiagnosis || `Rule-based alert: ${deal.riskSignals}.`;
const recommendedAction = parsed.recommendedAction || (
  deal.nextActivityOverdue
    ? 'Complete the overdue follow-up and log the outcome.'
    : 'Send a short email checking if the prospect needs clarification on pricing or implementation timeline.'
);
const suggestedEmailSubject = parsed.suggestedEmailSubject || `Quick question on ${deal.dealName}`;
const suggestedEmailBody = parsed.suggestedEmailBody || `Hi there,\n\nWanted to quickly float this to the top of your inbox as we approach our target timeline. Do you need any clarification on pricing or implementation steps from our side?\n\nBest,\n[Your Name]`;

const rescueAuditBlock = [
  `=== DEAL RESCUE AUDIT (${new Date().toISOString().split('T')[0]}) ===`,
  `Risk: ${riskLevel} (${deal.ruleRiskScore}/100) vert{} Classification:${classification}`,
  `Signals: ${deal.riskSignals}`,
  `AI Diagnosis: ${aiDiagnosis}`,
  `Recommended Action: ${recommendedAction}`,
  `Suggested Email Subject: ${suggestedEmailSubject}`,
  `Suggested Email Draft:\n${suggestedEmailBody}`
].join('\n');

return [
  {
    json: {
      ...deal,
      classification,
      riskLevel,
      aiDiagnosis,
      recommendedAction,
      suggestedEmailSubject,
      suggestedEmailBody,
      rescueAuditBlock,
      taskSubject: `Deal Rescue [${riskLevel}]: ${deal.dealName} ($${Number(deal.amount || 0).toLocaleString()})`,
      taskBody: `${aiDiagnosis}\n\nSignals: ${deal.riskSignals}\nRecommended Action:${recommendedAction}\n\n--- COPY SUGGESTED EMAIL ---\nSubject: ${suggestedEmailSubject}\n\n${suggestedEmailBody}`
    }
  }
];

