const allProcessed = $input.all().map(i => i.json).filter(d => d.classification && d.classification !== 'HEALTHY');

if (allProcessed.length === 0) {
  return [];
}

allProcessed.sort((a, b) => (b.amount - a.amount) || (b.ruleRiskScore - a.ruleRiskScore));

const totalRevenueAtRisk = allProcessed.reduce((sum, d) => sum + (Number(d.amount) || 0), 0);
const highRiskCount = allProcessed.filter(d => d.riskLevel === 'HIGH').length;

const topDealsText = allProcessed.slice(0, 10).map((d, idx) => {
  const formattedAmount = `$${Number(d.amount || 0).toLocaleString()}`;
  return [
    `*${idx + 1}.${d.dealName}* — *${d.riskLevel} RISK* (${formattedAmount})`,
    `• *Signals:* ${d.riskSignals}`,
    `• *AI Diagnosis (${d.classification}):*${d.aiDiagnosis}`,
    `• *Recommended Action:* ${d.recommendedAction}`,
    `• *Suggested Email (Subject: ${d.suggestedEmailSubject}):*`,
    `\`\`\`${d.suggestedEmailBody}\`\`\``
  ].join('\n');
}).join('\n\n---\n\n');

const slackReport = [
  `🚨 *HubSpot Deal Rescue Report* — *${allProcessed.length} Deal(s) At Risk* ($${totalRevenueAtRisk.toLocaleString()} Total Pipeline)`,
  `High Risk Deals: *${highRiskCount}* | Automatic Email Sending: *DISABLED (Rep Approval Required)*`,
  ``,
  topDealsText
].join('\n');

return [
  {
    json: {
      totalDealsAtRisk: allProcessed.length,
      highRiskCount,
      totalRevenueAtRisk,
      slackReport,
      deals: allProcessed
    }
  }
];
